using AiDocumentIntelligence.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace AiDocumentIntelligence.Infrastructure;

public class AppUserConfiguration : IEntityTypeConfiguration<AppUser>
{
    public void Configure(EntityTypeBuilder<AppUser> builder)
    {
        builder.HasKey(u => u.Id);
        // The id comes from Entra, never generated by the database.
        builder.Property(u => u.Id).ValueGeneratedNever();
        builder.Property(u => u.DisplayName).IsRequired().HasMaxLength(AppUser.MaxNameLength);
        builder.Property(u => u.Email).HasMaxLength(AppUser.MaxEmailLength);
    }
}
